    __balances['gameId'] = gameId
    max_extend = __balances['match_time'] * __balances['match_extend']
    __balances['game_time'] = now + datetime.timedelta(hours=int(max_extend))
    __balances['game_locked'] = False


@__export('con_soccer')
def play():
    account = ctx.caller
    operator_match = __operator.get()
    gameId = __balances['gameId']
    assert __balances['game_locked'
        ] == False, 'The match is finish!!!, please wait until current pot is distributed'
    play_before = __balances[gameId, account, 'play_before']
    if __balances[gameId, 'leaders', 'num_of_leaders'] == 0:
        __balances['match_extend'] = 1
        max_extend = __balances['match_time'] * __balances['match_extend']
        __balances['game_time'] = now + datetime.timedelta(hours=int(
            max_extend))
    if play_before == True:
        ammount_play = __balances['play_cost'] * decimal('0.20')
        assert currency.balance_of(account
            ) >= ammount_play, 'Not enough Balance to play!'
        currency.transfer_from(ammount_play, operator_match, account)
        __balances[gameId, 'jackpot'] += ammount_play
        __balances['jackpot'] += ammount_play
    else:
        ammount_play = __balances['play_cost']
        assert currency.balance_of(account
            ) >= ammount_play, 'Not enough Balance to play!'
        currency.transfer_from(ammount_play, operator_match, account)
        __balances[gameId, 'jackpot'] += ammount_play
        __balances['jackpot'] += ammount_play
        __balances[gameId, account, 'play_before'] = True
    __balances[gameId, account, 'can_play'] = True
    __balances[gameId, account, 'attempts'] += 1
    __balances[account, 'games_played'] += 1


@__export('con_soccer')
def set_score(score: float, goals: float, account: str):
    __assert_owner()
    gameId = __balances['gameId']
    __balances[account, 'goals'] += goals
    if __balances[gameId, 'best_score'] == score:
        __balances[gameId, 'leaders', 'num_of_leaders'] += 1
        num_leaders = __balances[gameId, 'leaders', 'num_of_leaders']
        __balances[gameId, 'leaders', num_leaders] = account
    if __balances[gameId, 'best_score'] < score:
        __balances[gameId, 'best_score'] = score
        __balances[gameId, 'leaders', 'num_of_leaders'] = 1
        __balances[gameId, 'leaders', 1] = account
    if __balances[account, 'best_score'] < score:
        __balances[account, 'best_score'] = score
    __balances[account, 'soccer_point'] += score / 1000
    __balances[gameId, account, 'can_play'] = False


