    t = importlib.import_module(contract)
    owner = t.get_owner(uid)

    if owner == operator.get():
        transfer_ownership(contract, uid, account)

@export
def buy_item(contract: str, uid: str):
    t = importlib.import_module(contract)
    owner = t.get_owner(uid)
    sender = ctx.caller
    assert_already_owned(contract, uid, sender)
    price_amount = t.get_price_amount(uid)
    assert price_amount, uid + ' is not for sale'
    assert price_amount > 0, uid + ' is not for sale'
    assert currency.balance_of(sender
        ) >= price_amount, 'Not enough Balance to play!'
    currency.transfer_from(price_amount * decimal('0.97'), owner, sender)
    currency.transfer_from(price_amount * decimal('0.03'), operator.get(),
        sender)
    balances[owner, contract, 'active_item'] = ''
    transfer_ownership(contract, uid, sender)


@export
def sell_item(contract: str, uid: str, amount: int):
    t = importlib.import_module(contract)
    assert_ownership(contract, uid, ctx.caller)
    t.set_price(uid, amount)

@export
def sell_item_soccer_point(contract: str, uid: str, amount: int):
    t = importlib.import_module(contract)
    assert_ownership(contract, uid, ctx.caller)
    t.set_price_soccer_point(uid, amount)


@export
def like_item(contract: str, uid: str):
    sender = ctx.caller
    t = importlib.import_module(contract)
    assert balances[contract, 'liked', uid, sender
        ] == '', sender + ' already liked ' + uid
    t.like_thing(uid)
    balances[contract, 'liked', uid, sender] = True


def assert_already_owned(contract: str, uid: str, sender):
    t = importlib.import_module(contract)
    owner = t.get_owner(uid)
    assert owner != sender, uid + ' already owned by ' + sender


def transfer_ownership(contract: str, uid: str, new_owner: str):
    t = importlib.import_module(contract)
    old_owner = t.get_owner(uid)
    t.set_owner(uid, new_owner)
    if t.get_price_amount(uid) > 0:
        t.set_price(uid, 0)


def assert_ownership(contract: str, uid: str, sender):
    t = importlib.import_module(contract)
    owner = t.get_owner(uid)
    assert owner == sender, uid + ' not owned by ' + sender


def assert_owner():
    assert ctx.caller == operator.get(), 'Only operator can call!'
